-- Generated from the map prototype and simplified boundary assets.
-- Provides initial geography keys, display names, and centroids for map visualization.

ON DUPLICATE KEY UPDATE
  parent_geo_key = VALUES(parent_geo_key),
  country = VALUES(country),
  province = VALUES(province),
  city = VALUES(city),
  display_name = VALUES(display_name),
  latitude = VALUES(latitude),
  longitude = VALUES(longitude),
  is_mappable = VALUES(is_mappable),
  coordinate_source = VALUES(coordinate_source);
